import heapq

def employee_free_time(schedules):
    heap = []
    for i, employee in enumerate(schedules):
        if employee:
            heapq.heappush(heap, (employee[0][0], employee[0][1], i, 0))

    result = []
    prev_end = None

    while heap:
        start, end, emp_idx, interval_idx = heapq.heappop(heap)

        if prev_end is not None and start > prev_end:
            result.append([prev_end, start])

        prev_end = max(prev_end, end) if prev_end is not None else end

        if interval_idx + 1 < len(schedules[emp_idx]):
            nxt = schedules[emp_idx][interval_idx + 1]
            heapq.heappush(heap, (nxt[0], nxt[1], emp_idx, interval_idx + 1))

    return result

